// Enhanced application with improved error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Set security HTTP headers
app.use(helmet());

// Enable CORS
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : true,
  credentials: true
}));

// Limit requests from same API
const limiter = rateLimit({
  max: 100,
  windowMs: 60 * 60 * 1000, // 1 hour
  message: 'Too many requests from this IP, please try again in an hour!'
});
app.use('/api', limiter);

// Body parser, reading data from body into req.body
app.use(express.json({ limit: '10kb' })); // Limit body size

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: [] // Add parameters that are allowed to have duplicates
}));

// Serving static files
app.use(express.static(`${__dirname}/public`));

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  // Validate query parameters if any
  const { detailed } = req.query;

  // Basic validation
  if (detailed && typeof detailed !== 'string') {
    return res.status(400).json({
      status: 'fail',
      message: 'Query parameter "detailed" must be a string'
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    ...(detailed === 'true' && { uptime: process.uptime() })
  });
});

// Users endpoint with proper error handling
app.get('/users', async (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset, sort } = req.query;

    // Validate limit and offset are numbers if provided
    if (limit && isNaN(Number(limit))) {
      return res.status(400).json({
        status: 'fail',
        message: 'Query parameter "limit" must be a number'
      });
    }

    if (offset && isNaN(Number(offset))) {
      return res.status(400).json({
        status: 'fail',
        message: 'Query parameter "offset" must be a number'
      });
    }

    // Validate sort parameter against allowed values
    if (sort && !['name', 'email', 'id'].includes(sort)) {
      return res.status(400).json({
        status: 'fail',
        message: 'Query parameter "sort" must be one of: name, email, id'
      });
    }

    // Simulate async operation (in real app, this would be a database call)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if specified
    let filteredUsers = users;
    if (limit || offset) {
      const start = parseInt(offset) || 0;
      const end = start + (parseInt(limit) || users.length);
      filteredUsers = users.slice(start, end);
    }

    // Apply sorting if specified
    if (sort) {
      filteredUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    res.json({
      status: 'success',
      results: filteredUsers.length,
      data: {
        users: filteredUsers
      }
    });
  } catch (err) {
    // Pass errors to error handling middleware
    next(err);
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);

    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;

// Global error handling controller
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // 1) Log error
    console.error('ERROR 💥', err);

    // 2) Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went very wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  // Set default values if not provided by AppError
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    sendErrorProd(error, res);
  }
};

