const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // 1) Log error
    console.error('ERROR 💥', err);

    // 2) Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    sendErrorProd(error, res);
  }
};
```

### Key Security Improvements:

1. **Input Validation & Sanitization**:
   - Validate all query parameters (type checking, range validation)
   - Sanitize inputs against XSS and NoSQL injection
   - Limit request body size to prevent DoS attacks

2. **Error Handling**:
   - Consistent error responses with appropriate HTTP status codes
   - Separate error handling for development vs production
   - Prevent stack trace leakage in production
   - Async error handling with try/catch and next(err)

3. **Security Headers & Protections**:
   - Helmet.js for HTTP header security
   - Rate limiting to prevent brute force attacks
   - XSS protection
   - NoSQL injection prevention
   - HTTP parameter pollution protection

4. **Information Disclosure Prevention**:
   - Generic error messages in production
   - Limited information in health checks
   - Controlled data exposure

5. **API Design Improvements**:
   - Proper HTTP status codes
   - Consistent response format
   - Pagination with validation
   - Versionable API structure (/api prefix for rate limiting)

These improvements follow security best practices including the OWASP Top 10 principles, particularly addressing injection attacks, broken authentication, sensitive data exposure, and security misconfiguration.

