const request = require('supertest');
const app = require('./app');

describe('API Endpoints', () => {
  describe('GET /health', () => {
    it('should return status ok', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('status', 'ok');
    });
  });

  describe('GET /users', () => {
    it('should return users with default pagination', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('data');
      expect(Array.isArray(res.body.data)).toBeTruthy();
    });

    it('should validate query parameters', async () => {
      const res = await request(app).get('/users?limit=invalid');
      expect(res.statusCode).toEqual(400);
      expect(res.body).toHaveProperty('error', 'Validation failed');
    });

    it('should limit maximum results', async () => {
      const res = await request(app).get('/users?limit=200');
      expect(res.statusCode).toEqual(200);
      // Should be limited to max 100 per our validation
      expect(res.body.data.length).toBeLessThanOrEqual(10);
    });

    it('should handle search parameter', async () => {
      const res = await request(app).get('/users?search=Ali');
      expect(res.statusCode).toEqual(200);
      expect(res.body.data.length).toBeGreaterThan(0);
    });
  });

  describe('Error Handling', () => {
    it('should return 404 for unknown routes', async () => {
      const res = await request(app).get('/unknown');
      expect(res.statusCode).toEqual(404);
      expect(res.body).toHaveProperty('error', 'Not found');
    });
  });
});

