// Improved application with enhanced error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { validate } = require('express-validation');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(cors()); // CORS protection
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // XSS prevention
app.use(mongoSanitize()); // MongoDB injection prevention
app.use(hpp()); // HTTP parameter pollution protection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation schemas
const userQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    sort: Joi.string().valid('name', 'email', 'id').default('id'),
    order: Joi.string().valid('asc', 'desc').default('asc')
  })
};

const userIdSchema = {
  params: Joi.object({
    id: Joi.number().integer().positive().required()
  })
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users list endpoint with validation
app.get('/users', validate(userQuerySchema), (req, res) => {
  try {
    // In a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination and sorting based on validated query params
    const { limit, offset, sort, order } = req.query;
    const sortedUsers = [...users].sort((a, b) => {
      if (order === 'asc') {
        return a[sort] > b[sort] ? 1 : -1;
      }
      return a[sort] < b[sort] ? 1 : -1;
    });

    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length
      }
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Individual user endpoint with validation
app.get('/users/:id', validate(userIdSchema), (req, res) => {
  try {
    const { id } = req.params;

    // In a real app, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found',
        timestamp: new Date().toISOString()
      });
    }

    res.json({ 
      data: user,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.all('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    timestamp: new Date().toISOString(),
    path: req.originalUrl
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', {
    message: error.message,
    stack: error.stack,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Handle Joi validation errors
  if (error.isJoi) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(detail => detail.message),
      timestamp: new Date().toISOString()
    });
  }

  // Handle Express validation errors
  if (error.status) {
    return res.status(error.status).json({
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }

  // Default error response
  res.status(500).json({
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

