// Improved application with enhanced error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with minimal information disclosure
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Users endpoint with input validation
app.get('/users', 
  // Validate query parameters
  [
    // Validate 'limit' query parameter if used
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    // Validate 'offset' query parameter if used
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Mock user data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // In a real implementation, apply pagination based on validated query params
    res.json({
      data: users,
      count: users.length
    });
  }
);

// Example POST endpoint with comprehensive validation
app.post('/users',
  [
    // Validate and sanitize input
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ max: 50 })
      .withMessage('Name must not exceed 50 characters'),

    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Please provide a valid email')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be a number between 0 and 150')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real application, you would save the user to a database here
    const newUser = {
      id: Date.now(), // Simple ID generation for demo
      ...req.body
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  }
);

// 404 handler - should be placed after all route definitions
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource could not be found'
  });
});

// Centralized error handling middleware
// Should be placed after all routes and middleware
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log error for internal monitoring

  // Determine status code
  const statusCode = err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: err.message || 'Internal Server Error'
  };

  // In development, provide more details
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.details = err;
  }

  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Perform cleanup operations before exiting
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

