// Enhanced application with improved error handling and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validateUserQuery } = require('./middleware/validation');
const errorHandler = require('./middleware/errorHandler');
const notFoundHandler = require('./middleware/notFoundHandler');
const logger = require('./middleware/logger');

const app = express();

// Security middleware
app.use(helmet()); // Adds various security headers

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging
app.use(logger);

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', validateUserQuery, (req, res) => {
  // In a real app, this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filtering based on validated query parameters
  const filteredUsers = users.filter(user => {
    if (req.query.name && !user.name.toLowerCase().includes(req.query.name.toLowerCase())) {
      return false;
    }
    if (req.query.email && !user.email.toLowerCase().includes(req.query.email.toLowerCase())) {
      return false;
    }
    return true;
  });

  res.json({
    count: filteredUsers.length,
    users: filteredUsers,
    timestamp: new Date().toISOString()
  });
});

// 404 handler - must come after all route definitions
app.use(notFoundHandler);

// Centralized error handling - must come last
app.use(errorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Input validation middleware
const { query } = require('express-validator');
const validate = require('./validate');

const validateUserQuery = [
  // Validate query parameters for users endpoint
  query('name')
    .optional()
    .isString()
    .trim()
    .escape()
    .isLength({ max: 100 })
    .withMessage('Name must be a string with maximum length of 100 characters'),

  query('email')
    .optional()
    .isString()
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Email must be a valid email address'),

  validate
];

module.exports = { validateUserQuery };

// Validation result handler
const { validationResult } = require('express-validator');

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

module.exports = validate;

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  // Log the error for debugging (in production, use proper logging service)
  console.error(`[${new Date().toISOString()}] Error:`, err);

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: {
      message: err.message || 'Internal Server Error',
      // Only include error details in development
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  };

  // Add validation error details if available
  if (err.validationErrors) {
    errorResponse.error.validationErrors = err.validationErrors;
  }

  res.status(statusCode).json(errorResponse);
};

module.exports = errorHandler;

// 404 Not Found handler
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    error: {
      message: `Route ${req.method} ${req.originalUrl} not found`
    }
  });
};

module.exports = notFoundHandler;

// Request logging middleware
const logger = (req, res, next) => {
  const start = Date.now();

  // Log incoming request
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);

  // Log response when it finishes
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} - ${res.statusCode} - ${duration}ms`);
  });

  next();
};

module.exports = logger;

